<script>
function reportBuilder(report,sources){return{form:JSON.parse(JSON.stringify(report)),sources,advanced:JSON.stringify(report.definition||{},null,2),error:'',previewMessage:'',previewResult:null,previewing:false,timer:null,get source(){return this.sources.find(s=>s.key===this.form.source)},changeSource(){this.form.definition.columns=[];this.advanced=JSON.stringify(this.form.definition,null,2);this.previewResult=null;},toggleColumn(key,checked){const a=this.form.definition.columns||[];this.form.definition.columns=checked?[...new Set([...a,key])]:a.filter(c=>c!==key);this.syncColumns();},syncColumns(){try{const d=JSON.parse(this.advanced);if(!d||Array.isArray(d)||typeof d!=='object')throw new Error();d.columns=this.form.definition.columns;this.advanced=JSON.stringify(d,null,2);this.error='';}catch(_){this.error='Definition must be a valid JSON object before syncing columns.';}},toggleRole(id,checked){this.form.role_ids=checked?[...new Set([...this.form.role_ids,id])]:this.form.role_ids.filter(x=>x!==id);},parsed(){const d=JSON.parse(this.advanced);if(!d||Array.isArray(d)||typeof d!=='object')throw new Error('Definition must be an object.');return d;},async preview(){this.previewing=true;this.error='';this.previewMessage='Running preview…';try{const r=await fetch('{{ route('reports.run') }}',{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({source:this.form.source,definition:this.parsed()})});const d=await r.json();if(!r.ok){this.previewResult=null;this.previewMessage='';this.error=(d.errors||[]).join(' ')||d.message||'Preview failed.';}else{this.previewResult=d.result;this.previewMessage=d.result?.truncated?'Preview results are truncated.':'Preview ready.';}}catch(e){this.previewResult=null;this.previewMessage='';this.error=e.message||'Definition must be valid JSON.';}finally{this.previewing=false;}},append(form,key,v){if(v===null||v===undefined){form.append(key,'');return;}if(Array.isArray(v)){v.forEach((x,i)=>this.append(form,`${key}[${i}]`,x));return;}if(typeof v==='object'){Object.entries(v).forEach(([k,x])=>this.append(form,key?`${key}[${k}]`:k,x));return;}form.append(key,String(v));},submit(event){try{this.form.definition=this.parsed();this.error='';}catch(e){this.error=e.message;return;}const f=event.currentTarget;f.querySelectorAll('[data-generated]').forEach(x=>x.remove());const data=new FormData();this.append(data,'definition',this.form.definition);this.form.role_ids.forEach((id,i)=>data.append(`role_ids[${i}]`,id));for(const[k,v]of data.entries()){const i=document.createElement('input');i.type='hidden';i.name=k;i.value=v;i.dataset.generated='1';f.append(i);}f.submit();}}}
</script>
